def d_H(s,t):
    count = 0

    # check for length
    if len(s) == len(t):
        for base_s, base_t in zip(s,t):
            if base_s != base_t:
                count += 1
            else:
                count += 0  
        print(count)

    else:
        print("Not equal length")



string_1 = ""
string_2 = ""

d_H(string_1, string_2)